mapper.select:

    	/*selectCountBuyerOwn*/                            
			SELECT  COUNT(*) AS COUNT
			FROM V_VOC_BUYEROWN A
			WHERE A.USER_ID = #{st_user_id}

/*getDashBoardList3*/ SELECT (SELECT COM_NAME_LOC FROM V_VOC_ICOMCMPY WHERE COM_CODE = X.BUYER AND SYS_TYPE = X.SYS_TYPE AND BUSINESS_COND LIKE '%B%') AS BUYER_NAME, X.BUYER_ALL_CNT, X.BUYER_CPL_CNT, ROUND((X.BUYER_CPL_CNT/X.BUYER_ALL_CNT)*100) AS BUYER_CPL_PCT, X.BUYER, X.SYS_TYPE FROM ( SELECT A.BUYER, NVL(COUNT(A.VC_NO),0) AS BUYER_ALL_CNT, NVL(SUM(DECODE(A.RECV_FLAG,'FB',1)),0) AS BUYER_CPL_CNT, A.SYS_TYPE FROM KEPAVCDT A, (SELECT CODE FROM ICOMCOD1 WHERE TYPE = 'VC01' AND TEXT3 = 'C') B WHERE TO_CHAR(A.CD_DATE,'YYYYMMDD') BETWEEN #{st_from_date} AND #{st_to_date} AND A.CLAIM_TYPE = B.CODE
AND (SYS_TYPE, BUYER) IN (SELECT SYS_TYPE, BUYER FROM V_VOC_BUYEROWN BOWN WHERE USER_ID=#{st_user_id})
GROUP BY A.BUYER, A.SYS_TYPE ) X ORDER BY BUYER_NAME
